import 'package:flutter/material.dart';
import '../../../services/auth/auth_service.dart';
import '../../../services/personal_ai/life_dashboard_service.dart';
class AurenLifeDashboardScreen extends StatefulWidget{const AurenLifeDashboardScreen({super.key});@override State<AurenLifeDashboardScreen> createState()=>_AurenLifeDashboardScreenState();}
class _AurenLifeDashboardScreenState extends State<AurenLifeDashboardScreen>{final _auth=FirebaseAurenAuthService();late Future<AurenLifeDashboard> f;@override void initState(){super.initState();f=_load();}Future<AurenLifeDashboard> _load()async{final u=_auth.currentUserId;if(u==null)throw StateError('Sign in required');return LifeDashboardService().load(u);} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('AUREN Life Dashboard')),body:FutureBuilder<AurenLifeDashboard>(future:f,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final x=s.data!;return ListView(padding:const EdgeInsets.all(20),children:[Text('نظرة واحدة على حياتك الرقمية',style:Theme.of(c).textTheme.headlineSmall),const SizedBox(height:16),_card('Goals',x.activeGoals.toString(),'متوسط التقدم '+x.averageProgress.toString()+'%'),_card('Memory',x.memories.toString(),'ذكريات مفعّلة'),_card('Business',x.businesses.toString(),'أنشطة'),_card('Marketplace',x.products.toString(),'منتجات وخدمات'),_card('Pulse',x.posts.toString(),'منشورات'),_card('Opportunities',x.opportunities.toString(),'فرص عامة متاحة')]);}));Widget _card(String a,String b,String d)=>Card(child:ListTile(title:Text(a),trailing:Text(b,style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold)),subtitle:Text(d)));}